            L.push(`${d.sku} at ${d.warehouse}: forecast ${d.total} units over ${(d.forecast || []).length} days (${d.method}, ${d.model_version}); back-test over ${b.holdout_days} days: WAPE ${b.wape_pct}% vs naive ${b.naive_same_weekday_wape_pct}%.`)
